import { useEffect, useMemo, useState } from "react";
import Editor from "@monaco-editor/react";
import "./App.css";

const LANGUAGE_CONFIG = {
  JavaScript: { icon: "⚡", ext: "js", color: "#f7df1e" },
  Python: { icon: "🐍", ext: "py", color: "#4db6ac" },
  Java: { icon: "☕", ext: "java", color: "#ff8a65" },
  "C++": { icon: "⚙️", ext: "cpp", color: "#64b5f6" },
};

function Toast({ message, type, onClose }) {
  useEffect(() => {
    const t = setTimeout(onClose, 3000);
    return () => clearTimeout(t);
  }, [onClose]);

  return <div className={`toast toast-${type}`}>{message}</div>;
}

function escapeHtml(s) {
  return String(s)
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#39;");
}

function renderMarkdown(raw) {
  if (!raw) return "";

  let safe = escapeHtml(raw);

  const blocks = [];

  safe = safe.replace(/```[\w-]*\n?([\s\S]*?)```/g, (_, code) => {
    const idx = blocks.push(code) - 1;
    return `@@CODEBLOCK_${idx}@@`;
  });

  safe = safe
    .replace(/^### (.+)$/gm, '<h3 class="md-h3">$1</h3>')
    .replace(/^## (.+)$/gm, '<h2 class="md-h2">$1</h2>')
    .replace(/^# (.+)$/gm, '<h1 class="md-h1">$1</h1>')
    .replace(/\*\*(.+?)\*\*/g, "<strong>$1</strong>")
    .replace(/\*(.+?)\*/g, "<em>$1</em>")
    .replace(/`([^`]+)`/g, '<code class="md-inline">$1</code>')
    .replace(/^---$/gm, '<hr class="md-hr" />');

  safe = safe
    .replace(
      /^\s*\d+\.\s+(.+)$/gm,
      '<div class="md-item md-num"><span class="md-bullet">›</span><span>$1</span></div>'
    )
    .replace(
      /^\s*[-*]\s+(.+)$/gm,
      '<div class="md-item"><span class="md-bullet">•</span><span>$1</span></div>'
    );

  const chunks = safe.split(/\n{2,}/).filter(Boolean);

  const html = chunks
    .map((c) =>
      /^<h\d|^<hr|^<div class="md-item/.test(c.trim())
        ? c
        : `<p class="md-p">${c.replace(/\n/g, "<br/>")}</p>`
    )
    .join("");

  return html.replace(/@@CODEBLOCK_(\d+)@@/g, (_, n) => {
    const code = blocks[Number(n)] ?? "";
    return `<div class="md-block"><pre><code>${code}</code></pre></div>`;
  });
}

export default function App() {
  const [code, setCode] = useState("");
  const [language, setLanguage] = useState("Python");

  const [review, setReview] = useState("");
  const [output, setOutput] = useState("");

  const [loading, setLoading] = useState(false);
  const [executing, setExecuting] = useState(false);

  const [toast, setToast] = useState(null);

  const lines = code.split("\n").length;
  const chars = code.length;

  const lang = LANGUAGE_CONFIG[language];

  const notify = (message, type = "success") =>
    setToast({ message, type });

  const apiBase = useMemo(() => {
    return "http://127.0.0.1:8000";
  }, []);

  const reviewCode = async () => {

    if (!code.trim()) {
      notify("Paste some code first.", "error");
      return;
    }

    setLoading(true);
    setReview("");

    try {

      const res = await fetch(`${apiBase}/review`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          code,
          language,
        }),
      });

      const data = await res.json();

      if (!res.ok || data.error) {

        setReview(
          data.error || "Backend error occurred."
        );

        notify("Review failed.", "error");

        return;
      }

      const finalReview =
        data.review ||
        data.response ||
        data.result ||
        data.message ||
        "";

      setReview(finalReview);

      notify("Review generated successfully!");

    } catch (err) {

      console.error(err);

      setReview(
        `Cannot connect to backend at ${apiBase}`
      );

      notify("Connection error.", "error");

    } finally {

      setLoading(false);

    }
  };

  const executeCode = async () => {

    if (!code.trim()) {
      notify("Paste some code first.", "error");
      return;
    }

    setExecuting(true);
    setOutput("");

    try {

      const res = await fetch(`${apiBase}/execute`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          code,
          language,
        }),
      });

      const data = await res.json();

      if (!res.ok || data.error) {

        setOutput(
          String(
            data.error || "Execution failed."
          )
        );

        notify("Execution failed.", "error");

        return;
      }

      setOutput(
        String(
          data.output ||
          data.error ||
          "No output"
        )
      );

      notify("Code executed!");

    } catch (err) {

      console.error(err);

      setOutput(
        `Cannot connect to backend at ${apiBase}`
      );

      notify("Execution error.", "error");

    } finally {

      setExecuting(false);

    }
  };

  const copyText = async (text, label) => {

    if (!text) return;

    await navigator.clipboard.writeText(text);

    notify(`${label} copied!`);
  };

  const clearAll = () => {
    setCode("");
    setReview("");
    setOutput("");
    notify("Cleared.");
  };

  return (
    <div className="app">

      {toast && (
        <Toast
          key={Date.now()}
          message={toast.message}
          type={toast.type}
          onClose={() => setToast(null)}
        />
      )}

      <header className="hdr">

        <div className="hdr-brand">
          <span className="brand-glyph">◈</span>
          <span className="brand-name">CodeSense</span>
          <span className="brand-tag">AI</span>
        </div>

        <span className="hdr-hint">
          Ctrl + Enter to review
        </span>

      </header>

      <div className="workspace">

        <div className="panel">

          <div className="panel-chrome">

            <span className="dot dot-r" />
            <span className="dot dot-y" />
            <span className="dot dot-g" />

            <span className="panel-filename">
              {lang.icon} editor.{lang.ext}
            </span>

            <div className="chrome-actions">

              <select
                className="lang-pick"
                value={language}
                onChange={(e) =>
                  setLanguage(e.target.value)
                }
              >
                {Object.entries(LANGUAGE_CONFIG).map(
                  ([l, v]) => (
                    <option key={l} value={l}>
                      {v.icon} {l}
                    </option>
                  )
                )}
              </select>

              <button
                className="cta-ghost"
                onClick={() =>
                  copyText(code, "Code")
                }
              >
                ⎘
              </button>

              <button
                className="cta-ghost cta-red"
                onClick={clearAll}
              >
                ✕
              </button>

            </div>
          </div>

          <div className="editor-wrap">

            <Editor
              height="100%"
              language={
                language === "Python"
                  ? "python"
                  : language === "JavaScript"
                  ? "javascript"
                  : language === "Java"
                  ? "java"
                  : "cpp"
              }
              theme="vs-dark"
              value={code}
              onChange={(value) => setCode(value || "")}
              options={{
                fontSize: 14,
                minimap: { enabled: false },
                automaticLayout: true,
                scrollBeyondLastLine: false,
                wordWrap: "on",
                tabSize: 2,
                fontFamily: "Fira Code, monospace",
              }}
            />

          </div>

          <div className="editor-bar">

            <span className="stat">{lines} ln</span>
            <span className="stat">{chars} ch</span>

            <span
              className="stat"
              style={{ color: lang.color }}
            >
              {lang.icon} {language}
            </span>

          </div>
        </div>

        <div className="panel panel-review-pane">

          <div className="panel-chrome">

            <span className="dot dot-r" />
            <span className="dot dot-y" />
            <span className="dot dot-g" />

            <span className="panel-filename">
              ◈ ai-review.md
            </span>

          </div>

          <div className="review-body">

            {loading ? (

              <div className="state-loading">
                <p>Analyzing code...</p>
              </div>

            ) : review ? (

              <div
                className="md-root"
                dangerouslySetInnerHTML={{
                  __html: renderMarkdown(review),
                }}
              />

            ) : (

              <div className="state-empty">
                <div className="empty-glyph">◈</div>
                <p>AI review appears here</p>
              </div>

            )}

          </div>
        </div>

        <div className="panel panel-review-pane">

          <div className="panel-chrome">

            <span className="dot dot-r" />
            <span className="dot dot-y" />
            <span className="dot dot-g" />

            <span className="panel-filename">
              ⚡ output.txt
            </span>

          </div>

          <div className="review-body">

            {executing ? (

              <div className="state-loading">
                <p>Executing code...</p>
              </div>

            ) : output ? (

              <pre className="output-box">
                {output}
              </pre>

            ) : (

              <div className="state-empty">
                <div className="empty-glyph">⚡</div>
                <p>Execution output appears here</p>
              </div>

            )}

          </div>
        </div>

      </div>

      <div className="action-bar">

        <button
          className={`review-btn ${
            loading ? "is-loading" : ""
          }`}
          onClick={reviewCode}
          disabled={loading}
        >
          {loading ? "Reviewing..." : "Review Code"}
        </button>

        <button
          className={`review-btn ${
            executing ? "is-loading" : ""
          }`}
          onClick={executeCode}
          disabled={executing}
        >
          {executing ? "Running..." : "Run Code"}
        </button>

      </div>

    </div>
  );
}
